import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd();

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run(['cargo', 'run', '-q', '-p', 'fz', '--', 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return payload

def messages(payload):
    return [item['message'] for item in payload['items']]

builders_pass = verify('proc_builders_pass', '''
    use core.proc;
    fn main() -> i32 {
        let argv = proc.argv_new()
        discard proc.argv_push(argv, "-lc")
        discard proc.argv_push(argv, "echo hi")
        let env = proc.env_new()
        discard proc.env_set(env, "K", "V")
        let handle = proc.spawn_cmd("/bin/sh", argv, env, "")
        discard proc.close(handle)
        return 0
    }
''', 0)
assert builders_pass['errors'] == 0, builders_pass
assert not any('linear value `argv` was not consumed/freed' in message for message in messages(builders_pass)), builders_pass
assert not any('linear value `env` was not consumed/freed' in message for message in messages(builders_pass)), builders_pass

builders_fail = verify('proc_builders_fail', '''
    use core.proc;
    fn main() -> i32 {
        let argv = proc.argv_new()
        discard proc.argv_push(argv, "-lc")
        let env = proc.env_new()
        discard proc.env_set(env, "K", "V")
        return 0
    }
''', 1)
assert any('linear value `argv` was not consumed/freed' in message for message in messages(builders_fail)), builders_fail
assert any('linear value `env` was not consumed/freed' in message for message in messages(builders_fail)), builders_fail
assert any('leaks allocation' in message and '`argv`' in message for message in messages(builders_fail)), builders_fail
assert any('leaks allocation' in message and '`env`' in message for message in messages(builders_fail)), builders_fail

wrapper_pass = verify('proc_builders_wrapper_pass', '''
    use core.proc;
    fn launch(argv: ProcessArgv, env: ProcessEnv) -> ProcessHandle {
        return proc.spawn_cmd("/bin/sh", argv, env, "")
    }
    fn main() -> i32 {
        let argv = proc.argv_new()
        discard proc.argv_push(argv, "-lc")
        discard proc.argv_push(argv, "echo hi")
        let env = proc.env_new()
        discard proc.env_set(env, "K", "V")
        let handle = launch(argv, env)
        discard proc.close(handle)
        return 0
    }
''', 0)
assert wrapper_pass['errors'] == 0, wrapper_pass
assert not any('linear value `argv` was not consumed/freed' in message for message in messages(wrapper_pass)), wrapper_pass
assert not any('linear value `env` was not consumed/freed' in message for message in messages(wrapper_pass)), wrapper_pass

print('compiler-memory-process-builders-ok')

